split_array_largest_sum.brute:
best_split(start, pieces):
    if pieces == 1: return sum of nums[start..]   (the last piece takes what is left)
    best = +inf, piece_sum = 0
    for each end from start while enough elements remain for the other pieces:
        piece_sum += nums[end]
        rest = best_split(end + 1, pieces - 1)
        best = min(best, max(piece_sum, rest))
    return best
return best_split(0, k)

split_array_largest_sum.optimal:
pieces_needed(cap):
    count = 1, current = 0
    for each value in nums:
        if current + value > cap: count += 1, current = 0   (start a new piece)
        current += value
    return count
left = max of nums, right = sum of nums
while left < right:
    mid = (left + right) / 2
    if pieces_needed(mid) <= k: right = mid   (cap mid works, try smaller)
    else: left = mid + 1
return left

maximum_average_subarray_ii.brute:
best = -inf
for each start:
    total = 0
    for each end from start to n - 1:
        total += nums[end], length = end - start + 1
        if length >= k: best = max(best, total / length)
return best

minimum_interval_to_include_each_query.brute:
answers = empty list
for each query q:
    best = -1
    for each (left, right) in intervals:
        if left <= q <= right:
            size = right - left + 1
            if best == -1 or size < best: best = size
    append best to answers
return answers

minimum_interval_to_include_each_query.optimal:
sort intervals by left edge
order = (query value, original position) for every query, sorted
answers = -1 for every query, candidates = empty min-heap of (size, right), next_interval = 0
for each (q, position) in order:
    while next_interval < count and intervals[next_interval].left <= q:
        push (right - left + 1, right) of that interval, next_interval += 1   (it has started)
    while candidates is not empty and the top's right < q:
        pop the top   (ended before q: drop it lazily)
    if candidates is not empty: answers[position] = size of the top
return answers

rectangle_area_ii.brute:
xs = sorted distinct x edges, ys = sorted distinct y edges   (coordinate compression)
painted = grid of (count of xs - 1) x (count of ys - 1) cells, all false
for each rectangle (x1, y1, x2, y2):
    for each cell column i from index of x1 up to index of x2:
        for each cell row j from index of y1 up to index of y2:
            painted[i][j] = true
area = 0
for each cell (i, j):
    if painted[i][j]: area += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j])
return area mod 1e9+7
